// Парсинг HTML от TGStat
const html = $input.item.json.data || $input.item.json.body || '';
const channels = [];

// Регулярки для извлечения данных
const channelPattern = /<a[^>]*href="[^"]*\/channel\/@?([a-zA-Z][a-zA-Z0-9_]{3,})"[^>]*>/gi;
const titlePattern = /<[^>]*class="[^"]*channel-title[^"]*"[^>]*>([^<]+)</gi;
const subsPattern = /(\d+(?:[.,]\d+)?)[\s]*(K|М|M|к|тыс|млн)?[\s]*(?:подписчик|subscriber|sub)/gi;

let match;
const usernames = new Set();

// Ищем все ссылки на каналы
while ((match = channelPattern.exec(html)) !== null) {
  const username = match[1].toLowerCase();
  if (!usernames.has(username) && username.length >= 4) {
    usernames.add(username);

    // Пытаемся найти подписчиков рядом
    let subscribers = 0;
    const context = html.substring(Math.max(0, match.index - 500), match.index + 500);
    const subsMatch = subsPattern.exec(context);
    if (subsMatch) {
      let num = parseFloat(subsMatch[1].replace(',', '.'));
      const mult = subsMatch[2]?.toLowerCase() || '';
      if (mult === 'k' || mult === 'к' || mult === 'тыс') num *= 1000;
      if (mult === 'm' || mult === 'м' || mult === 'млн') num *= 1000000;
      subscribers = Math.round(num);
    }

    channels.push({
      username: username,
      link: `https://t.me/${username}`,
      subscribers: subscribers,
      source: 'tgstat',
      title: username
    });
  }
}

// Если не нашли через регулярки, пробуем простой поиск t.me ссылок
if (channels.length === 0) {
  const tmePattern = /t\.me\/([a-zA-Z][a-zA-Z0-9_]{3,31})/gi;
  while ((match = tmePattern.exec(html)) !== null) {
    const username = match[1].toLowerCase();
    if (!usernames.has(username) && 
        !['joinchat', 'addstickers', 'share', 'proxy'].includes(username)) {
      usernames.add(username);
      channels.push({
        username: username,
        link: `https://t.me/${username}`,
        subscribers: 0,
        source: 'tgstat',
        title: username
      });
    }
  }
}

return channels.slice(0, 30).map(ch => ({json: ch}));

// Парсинг HTML от Telega.in
const html = $input.item.json.data || $input.item.json.body || '';
const channels = [];
const usernames = new Set();

// Ищем ссылки на каналы
const patterns = [
  /t\.me\/([a-zA-Z][a-zA-Z0-9_]{3,31})/gi,
  /href="[^"]*@([a-zA-Z][a-zA-Z0-9_]{3,31})"/gi
];

for (const pattern of patterns) {
  let match;
  while ((match = pattern.exec(html)) !== null) {
    const username = match[1].toLowerCase();
    if (!usernames.has(username) && 
        !['joinchat', 'addstickers', 'share', 'proxy', 'login'].includes(username)) {
      usernames.add(username);

      // Пытаемся найти цену
      let price = '';
      const context = html.substring(Math.max(0, match.index - 300), match.index + 300);
      const priceMatch = context.match(/(\d+(?:\s*\d+)*)\s*(?:₽|руб|RUB)/i);
      if (priceMatch) {
        price = priceMatch[0];
      }

      channels.push({
        username: username,
        link: `https://t.me/${username}`,
        subscribers: 0,
        source: 'telega',
        title: username,
        price: price
      });
    }
  }
}

return channels.slice(0, 30).map(ch => ({json: ch}));

// Дедупликация и скоринг каналов
const allItems = $input.all();
const channelMap = new Map();

for (const item of allItems) {
  const ch = item.json;
  const username = ch.username?.toLowerCase();

  if (!username || username.length < 4) continue;

  if (channelMap.has(username)) {
    // Обновляем данные если есть больше информации
    const existing = channelMap.get(username);
    if (ch.subscribers > existing.subscribers) {
      existing.subscribers = ch.subscribers;
    }
    if (ch.price && !existing.price) {
      existing.price = ch.price;
    }
    existing.sources = (existing.sources || existing.source) + ',' + ch.source;
  } else {
    channelMap.set(username, {...ch});
  }
}

// Конвертируем в массив и скорим
const channels = Array.from(channelMap.values()).map(ch => {
  let score = 50; // Базовый скор

  // За подписчиков
  if (ch.subscribers >= 100000) score += 30;
  else if (ch.subscribers >= 50000) score += 25;
  else if (ch.subscribers >= 10000) score += 20;
  else if (ch.subscribers >= 5000) score += 15;
  else if (ch.subscribers >= 1000) score += 10;

  // За нахождение на двух площадках
  if (ch.sources && ch.sources.includes(',')) score += 10;

  // За наличие цены (значит канал активно рекламируется)
  if (ch.price) score += 5;

  return {
    ...ch,
    score: Math.min(100, score)
  };
});

// Сортируем по скору
channels.sort((a, b) => b.score - a.score);

// Возвращаем топ-20
return channels.slice(0, 20).map((ch, idx) => ({
  json: {
    position: idx + 1,
    username: ch.username,
    link: ch.link,
    subscribers: ch.subscribers || 'N/A',
    subscribers_formatted: ch.subscribers >= 1000000 
      ? (ch.subscribers / 1000000).toFixed(1) + 'M'
      : ch.subscribers >= 1000 
        ? (ch.subscribers / 1000).toFixed(1) + 'K'
        : ch.subscribers || 'N/A',
    source: ch.sources || ch.source,
    price: ch.price || '',
    score: ch.score
  }
}));

// Обогащаем данными из Telegram API
const items = $input.all();
const results = [];

for (const item of items) {
  const original = item.json;
  const apiResponse = original.result || {};

  // Канал живой если получили данные
  const isAlive = !!apiResponse.id;

  results.push({
    json: {
      position: original.position || results.length + 1,
      username: original.username || apiResponse.username,
      title: apiResponse.title || original.username,
      link: original.link || `https://t.me/${apiResponse.username}`,
      subscribers: apiResponse.member_count || original.subscribers || 'N/A',
      is_alive: isAlive,
      status: isAlive ? '✅ Живой' : '❓ Не проверен',
      source: original.source || 'parsed',
      price: original.price || '',
      score: original.score || 50,
      description: (apiResponse.description || '').substring(0, 100)
    }
  });
}

// Сортируем: живые вверх, потом по скору
results.sort((a, b) => {
  if (a.json.is_alive !== b.json.is_alive) {
    return b.json.is_alive ? 1 : -1;
  }
  return b.json.score - a.json.score;
});

// Перенумеровываем
results.forEach((r, i) => r.json.position = i + 1);

return results;

